extra_css:
/* Tourbillon surfaces: smoked sapphire over the movement. Panels are dark glass with a polished bevel (bright top edge, darker
   lower edge), a faint violet anti-reflection sheen and a hairline gilt rim; hover sends Cotes de Geneve stripes across the glass.
   Scoped to own surfaces only. */
html[data-atmo="tourbillon"] .card, html[data-atmo="tourbillon"] .panel, html[data-atmo="tourbillon"] .gx-card {
  background: linear-gradient(168deg, rgba(120,110,200,.07), transparent 38%), linear-gradient(180deg, rgba(28,31,40,.88), rgba(11,12,16,.94));
  backdrop-filter: blur(10px) saturate(1.1); -webkit-backdrop-filter: blur(10px) saturate(1.1);
  box-shadow: inset 0 1px 0 rgba(255,255,255,.13), inset 0 -1px 0 rgba(0,0,0,.6), inset 0 0 0 1px rgba(214,178,110,.16), 0 18px 46px rgba(0,0,0,.72);
  transition: box-shadow .35s ease, transform .5s cubic-bezier(.2,1,.3,1), background-position 1.1s cubic-bezier(.2,.8,.2,1); }
html[data-atmo="tourbillon"] .card:hover, html[data-atmo="tourbillon"] .gx-card:hover {
  transform: translateY(-2px);
  background: repeating-linear-gradient(-25deg, rgba(255,255,255,0) 0 18px, rgba(255,255,255,.035) 26px, rgba(255,255,255,0) 34px), linear-gradient(168deg, rgba(120,110,200,.09), transparent 38%), linear-gradient(180deg, rgba(30,33,43,.9), rgba(11,12,16,.95));
  box-shadow: inset 0 1px 0 rgba(255,255,255,.22), inset 0 0 0 1px rgba(214,178,110,.42), 0 0 24px rgba(143,168,255,.12), 0 22px 54px rgba(0,0,0,.76); }
html[data-atmo="tourbillon"] h1, html[data-atmo="tourbillon"] h2 { background: linear-gradient(180deg, #ffffff, #d3d6de 48%, #8f95a4); -webkit-background-clip: text; background-clip: text; color: transparent; }
html[data-atmo="tourbillon"] h1 { filter: drop-shadow(0 2px 14px rgba(0,0,0,.9)) drop-shadow(0 0 2px rgba(0,0,0,.85)); }   /* the title stays clear over bright stripes */

